session_start(); header('Content-Type: application/json; charset=utf-8'); require_once __DIR__.'/../../config/config.php';
if(empty($_SESSION['user_id'])){http_response_code(401);echo json_encode(['success'=>false,'message'=>'กรุณาเข้าสู่ระบบก่อน','login_url'=>'/pages/login.php']);exit;}
$input=json_decode(file_get_contents('php://input'),true)?:$_POST;$bookId=(int)($input['book_id']??0);$userId=(int)$_SESSION['user_id'];$action=$input['action']??'toggle';$source=($input['source']??'book')==='exchange'?'exchange':'book';
try{$table=$source==='exchange'?'exchange_wishlists':'wishlists';$idCol=$source==='exchange'?'exchange_id':'book_id';$pk=$source==='exchange'?'exchange_wishlist_id':'wishlist_id';$check=$pdo->prepare("SELECT $pk FROM $table WHERE user_id=? AND $idCol=?");$check->execute([$userId,$bookId]);$exists=(bool)$check->fetchColumn();if($action==='remove'||($action==='toggle'&&$exists)){$pdo->prepare("DELETE FROM $table WHERE user_id=? AND $idCol=?")->execute([$userId,$bookId]);$active=false;}else{$sourceTable=$source==='exchange'?'exchanges':'books';$sourceId=$source==='exchange'?'exchange_id':'book_id';$item=$pdo->prepare("SELECT 1 FROM $sourceTable WHERE $sourceId=?");$item->execute([$bookId]);if(!$item->fetchColumn())throw new RuntimeException('ไม่พบรายการ');$pdo->prepare("INSERT IGNORE INTO $table(user_id,$idCol) VALUES(?,?)")->execute([$userId,$bookId]);$active=true;}$count=$pdo->prepare('SELECT (SELECT COUNT(*) FROM wishlists WHERE user_id=?)+(SELECT COUNT(*) FROM exchange_wishlists WHERE user_id=?)');$count->execute([$userId,$userId]);echo json_encode(['success'=>true,'active'=>$active,'count'=>(int)$count->fetchColumn()]);}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
